def checks(P) -> dict:
    out = {"certified_relations": len(P.formulas()) == 86,
           "refuses_nonsense": not P.ask("What is it?").solved}
    for i, (q, v) in enumerate(QUESTIONS):
        a = P.ask(q)
        out[f"question_{i}"] = a.solved and abs(a.value - v) <= 1e-6 * max(1.0, abs(v))
    return out
